source='''def transform(grid):
    """Complete each same-color fragment as a translated copy of the color-4 motif."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    cells = {}
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v != 1:
                cells.setdefault(v, set()).add((r, c))
    motif_cells = cells[4]
    mr, mc = min(r for r, c in motif_cells), min(c for r, c in motif_cells)
    motif = {(r-mr, c-mc) for r, c in motif_cells}
    for color, pts in cells.items():
        if color in (1, 4):
            continue
        points = sorted(pts)
        # A color may mark more than one copy of the motif. Find a minimum
        # set of motif placements that covers all its observed cells.
        candidates = []
        for r0 in range(h):
            for c0 in range(w):
                shifted = {(r0+r, c0+c) for r, c in motif}
                if not all(0 <= r < h and 0 <= c < w for r, c in shifted):
                    continue
                covered = frozenset(p for p in points if p in shifted)
                if len(covered) >= 2:
                    candidates.append((covered, shifted))
        # Remove duplicate masks, keeping one placement for each.
        uniq = {}
        for covered, shifted in candidates:
            uniq.setdefault(covered, shifted)
        candidates = [(covered, shifted) for covered, shifted in uniq.items()]
        full = frozenset(points)
        best = None
        def search(remaining, chosen, start=0):
            nonlocal best
            if not remaining:
                if best is None or len(chosen) < len(best):
                    best = chosen[:]
                return
            if best is not None and len(chosen) >= len(best):
                return
            point = min(remaining, key=lambda p: sum(p in cov for cov, _ in candidates))
            for cov, shifted in candidates:
                if point in cov:
                    search(remaining - cov, chosen + [shifted])
        search(full, [])
        if best is None:
            raise ValueError(f"cannot cover all clues for color {color}")
        for shape in best:
            for r, c in shape:
                out[r][c] = color
    return out
